#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void max_reduce_kernel_vec4(
    const float* __restrict__ input,
    float* __restrict__ output,
    long outer_size,
    long dim_size,
    long inner_vec,
    long inner_size)
{
    long total = outer_size * inner_vec;
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long stride = blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        long outer = idx / inner_vec;
        long inner_block = idx % inner_vec;
        long inner = inner_block * 4;
        long base = outer * dim_size * inner_size + inner;
        float4 max_val = make_float4(-FLT_MAX, -FLT_MAX, -FLT_MAX, -FLT_MAX);
        #pragma unroll 4
        for (long k = 0; k < dim_size; ++k) {
            float4 v = *reinterpret_cast<const float4*>(&input[base + k * inner_size]);
            max_val.x = v.x > max_val.x ? v.x : max_val.x;
            max_val.y = v.y > max_val.y ? v.y : max_val.y;
            max_val.z = v.z > max_val.z ? v.z : max_val.z;
            max_val.w = v.w > max_val.w ? v.w : max_val.w;
        }
        float4* out_ptr = reinterpret_cast<float4*>(&output[outer * inner_size + inner]);
        *out_ptr = max_val;
    }
}
__global__ void max_reduce_kernel_scalar_tail(
    const float* __restrict__ input,
    float* __restrict__ output,
    long outer_size,
    long dim_size,
    long inner_size,
    long inner_start)
{
    long tail_size = inner_size - inner_start;
    long total = outer_size * tail_size;
    long idx = blockIdx.x * blockDim.x + threadIdx.x;
    long stride = blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        long outer = idx / tail_size;
        long inner_off = idx % tail_size;
        long inner = inner_start + inner_off;
        long base = outer * dim_size * inner_size + inner;
        float max_val0 = -FLT_MAX, max_val1 = -FLT_MAX, max_val2 = -FLT_MAX, max_val3 = -FLT_MAX;
        float max_val4 = -FLT_MAX, max_val5 = -FLT_MAX, max_val6 = -FLT_MAX, max_val7 = -FLT_MAX;
        float max_val8 = -FLT_MAX, max_val9 = -FLT_MAX, max_val10 = -FLT_MAX, max_val11 = -FLT_MAX;
        float max_val12 = -FLT_MAX, max_val13 = -FLT_MAX, max_val14 = -FLT_MAX, max_val15 = -FLT_MAX;
        long dim_size16 = dim_size - (dim_size % 16);
        long k = 0;
        #pragma unroll 2
        for (; k < dim_size16; k += 16) {
            float v0 = __ldg(&input[base + (k + 0) * inner_size]);
            float v1 = __ldg(&input[base + (k + 1) * inner_size]);
            float v2 = __ldg(&input[base + (k + 2) * inner_size]);
            float v3 = __ldg(&input[base + (k + 3) * inner_size]);
            float v4 = __ldg(&input[base + (k + 4) * inner_size]);
            float v5 = __ldg(&input[base + (k + 5) * inner_size]);
            float v6 = __ldg(&input[base + (k + 6) * inner_size]);
            float v7 = __ldg(&input[base + (k + 7) * inner_size]);
            float v8 = __ldg(&input[base + (k + 8) * inner_size]);
            float v9 = __ldg(&input[base + (k + 9) * inner_size]);
            float v10 = __ldg(&input[base + (k + 10) * inner_size]);
            float v11 = __ldg(&input[base + (k + 11) * inner_size]);
            float v12 = __ldg(&input[base + (k + 12) * inner_size]);
            float v13 = __ldg(&input[base + (k + 13) * inner_size]);
            float v14 = __ldg(&input[base + (k + 14) * inner_size]);
            float v15 = __ldg(&input[base + (k + 15) * inner_size]);
            max_val0 = v0 > max_val0 ? v0 : max_val0;
            max_val1 = v1 > max_val1 ? v1 : max_val1;
            max_val2 = v2 > max_val2 ? v2 : max_val2;
            max_val3 = v3 > max_val3 ? v3 : max_val3;
            max_val4 = v4 > max_val4 ? v4 : max_val4;
            max_val5 = v5 > max_val5 ? v5 : max_val5;
            max_val6 = v6 > max_val6 ? v6 : max_val6;
            max_val7 = v7 > max_val7 ? v7 : max_val7;
            max_val8 = v8 > max_val8 ? v8 : max_val8;
            max_val9 = v9 > max_val9 ? v9 : max_val9;
            max_val10 = v10 > max_val10 ? v10 : max_val10;
            max_val11 = v11 > max_val11 ? v11 : max_val11;
            max_val12 = v12 > max_val12 ? v12 : max_val12;
            max_val13 = v13 > max_val13 ? v13 : max_val13;
            max_val14 = v14 > max_val14 ? v14 : max_val14;
            max_val15 = v15 > max_val15 ? v15 : max_val15;
        }
        for (; k < dim_size; ++k) {
            float v = __ldg(&input[base + k * inner_size]);
            max_val0 = v > max_val0 ? v : max_val0;
        }
        float max_val = max_val0;
        max_val = max_val1 > max_val ? max_val1 : max_val;
        max_val = max_val2 > max_val ? max_val2 : max_val;
        max_val = max_val3 > max_val ? max_val3 : max_val;
        max_val = max_val4 > max_val ? max_val4 : max_val;
        max_val = max_val5 > max_val ? max_val5 : max_val;
        max_val = max_val6 > max_val ? max_val6 : max_val;
        max_val = max_val7 > max_val ? max_val7 : max_val;
        max_val = max_val8 > max_val ? max_val8 : max_val;
        max_val = max_val9 > max_val ? max_val9 : max_val;
        max_val = max_val10 > max_val ? max_val10 : max_val;
        max_val = max_val11 > max_val ? max_val11 : max_val;
        max_val = max_val12 > max_val ? max_val12 : max_val;
        max_val = max_val13 > max_val ? max_val13 : max_val;
        max_val = max_val14 > max_val ? max_val14 : max_val;
        max_val = max_val15 > max_val ? max_val15 : max_val;
        output[outer * inner_size + inner] = max_val;
    }
}
torch::Tensor max_reduce_cuda(torch::Tensor x, int64_t dim) {
    x = x.contiguous();
    int64_t ndim = x.dim();
    if (dim < 0) dim += ndim;
    int64_t outer_size = 1;
    for (int64_t i = 0; i < dim; ++i) outer_size *= x.size(i);
    int64_t dim_size = x.size(dim);
    int64_t inner_size = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) inner_size *= x.size(i);
    std::vector<int64_t> out_shape;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) out_shape.push_back(x.size(i));
    }
    auto output = torch::empty(out_shape, x.options());
    bool can_vectorize = (inner_size % 4 == 0);
    int64_t inner_vec = can_vectorize ? (inner_size / 4) : 0;
    int64_t inner_rem_start = can_vectorize ? (inner_vec * 4) : 0;
    int64_t tail_size = inner_size - inner_rem_start;
    int threads = 256;
    if (inner_vec > 0) {
        long total_vec = outer_size * inner_vec;
        int blocks = (total_vec + threads - 1) / threads;
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        max_reduce_kernel_vec4<<<blocks, threads>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            outer_size,
            dim_size,
            inner_vec,
            inner_size
        );
    }
    if (tail_size > 0) {
        long total_tail = outer_size * tail_size;
        int blocks_tail = (total_tail + threads - 1) / threads;
        if (blocks_tail > 65535) blocks_tail = 65535;
        if (blocks_tail < 1) blocks_tail = 1;
        max_reduce_kernel_scalar_tail<<<blocks_tail, threads>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            outer_size,
            dim_size,
            inner_size,
            inner_rem_start
        );
    }
    return output;
}
"""

